"""Public, user-opened reference URLs; never fetched or generated by the model."""

import ipaddress
import re
from urllib.parse import urlsplit

from pydantic import Field, field_validator

from .common import StrictModel


def public_advisory_url(value):
    if not isinstance(value, str) or len(value) > 2048 or re.search(r"[\s\x00-\x1f\x7f\\]", value):
        raise ValueError("Invalid advisory URL")
    parsed = urlsplit(value)
    host = (parsed.hostname or "").lower()
    if (
        parsed.scheme != "https"
        or parsed.username
        or parsed.password
        or parsed.fragment
        or parsed.port not in {None, 443}
        or "." not in host
        or not re.fullmatch(r"[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?", host)
        or host.endswith((".local", ".localhost", ".internal", ".lan", ".home.arpa"))
    ):
        raise ValueError("Advisories require a public HTTPS hostname")
    try:
        ipaddress.ip_address(host)
    except ValueError:
        pass
    else:
        raise ValueError("IP-address advisory URLs are not supported")
    return value


class CveAdvisory(StrictModel):
    url: str = Field(max_length=2048)

    @field_validator("url")
    @classmethod
    def public_url(cls, value):
        return public_advisory_url(value)
